import{_ as a,H as t,f as o,b as s,j as i,i as n}from"./chunks/framework.DLd0CbzH.js";const l="/app-mockup-en.webp",g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"OmniCraft ERP","text":"Smart accounting system for crafters","tagline":"Lean accounting without the routine. Turn leather, wood, and clay into a profitable business, not accounting chaos. Offline access, accurate cost calculation, and honest analytics.","image":{"src":"/logo.svg","alt":"OmniCraft ERP"},"actions":[{"theme":"brand","text":"Download for Windows ↓","link":"https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe"},{"theme":"alt","text":"Documentation →","link":"/docs/introduction"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function c(d,e,p,u,v,h){return t(),o("div",null,[...e[0]||(e[0]=[s("div",{id:"notice-banner",class:"notice-banner"},[s("div",{class:"notice-content"},[s("span",{class:"notice-icon"},"⚠️"),s("p",null,[i(" The website is still under development, but the software is already functional — you can download and try it now."),s("br"),i(" We will soon finalize the Terms of Service and make the license purchase available for all software versions. ")])]),s("button",{class:"notice-close",onclick:"document.getElementById('notice-banner').style.display='none'"},"×")],-1),n('<div class="glow-bg top-glow"></div><div class="custom-section showcase-section" style="padding-bottom:2rem;"><div class="section-container"><div class="showcase-wrapper"><div class="showcase-glow"></div><div class="showcase-window"><div class="window-header"><span class="dot red"></span><span class="dot yellow"></span><span class="dot green"></span></div><img src="'+l+'" alt="OmniCraft ERP Interface" class="ui-screenshot"><div class="window-fade"></div></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="split-layout"><div class="split-left"><h2 class="gradient-text text-left">The Evolution of Your Accounting</h2><p>Spreadsheets are a great tool to start. But when you have dozens of materials, a queue of orders, and floating logistics costs, manual accounting starts to slow down your workshop&#39;s growth.</p><p><strong>OmniCraft ERP</strong> is a professional next step. You stop writing formulas and start managing ready-made business metrics.</p></div><div class="split-right"><div class="vs-card"><div class="vs-column bad"><div class="vs-header">Regular Spreadsheets</div><ul><li><span class="icon">✕</span> No cascading raw material reservation</li><li><span class="icon">✕</span> Complex manual delivery cost distribution</li><li><span class="icon">✕</span> Broken formulas and rounding errors</li><li><span class="icon">✕</span> Impossible to write off batches by FIFO</li></ul></div><div class="vs-divider">VS</div><div class="vs-column good"><div class="vs-header brand">OmniCraft ERP</div><ul><li><span class="icon">✓</span> Dynamic Workbench with smart shortages</li><li><span class="icon">✓</span> Automatic MAC cost calculation</li><li><span class="icon">✓</span> 100% accuracy (integer architecture)</li><li><span class="icon">✓</span> Auto-depreciation of tools and equipment</li></ul></div></div></div></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="section-header" style="margin-bottom:2rem;"><h2 class="gradient-text">Who is OmniCraft perfect for?</h2><p class="section-subtitle">The system is designed to be universal: the cost math works equally accurately for any physical craft.</p></div><div class="audience-grid"><div class="audience-card"><span class="audience-icon">👜</span><h4>Leathercraft</h4><p>Accounting for square decimeters of hides, linear meters of straps, consumption of glue, chemicals, and expensive hardware.</p></div><div class="audience-card"><span class="audience-icon">🪚</span><h4>Woodworking</h4><p>Accounting for solid wood, plywood sheets, varnishes, and strict depreciation of CNC machines and tools.</p></div><div class="audience-card"><span class="audience-icon">🏺</span><h4>Ceramics &amp; Decor</h4><p>Accounting for kilograms of clay, liters of glaze, pigments, and depreciation of muffle kilns.</p></div><div class="audience-card"><span class="audience-icon">🧵</span><h4>Sewing Studios</h4><p>Accounting for rolls and yardage of fabrics, threads, hardware, and calculating the cost of seamstresses&#39; working hours.</p></div></div></div></div><div class="custom-section bento-section"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Everything a workshop needs.<br>In a single system.</h2><p class="section-subtitle">OmniCraft connects the warehouse, workbench, and cash register into a smart, continuous pipeline.</p></div><div class="bento-grid"><div class="bento-card"><div class="bento-bg-gradient"></div><div class="bento-icon-wrapper"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="4" width="16" height="16" rx="2" ry="2"></rect><line x1="9" y1="9" x2="15" y2="9"></line><line x1="9" y1="13" x2="15" y2="13"></line><line x1="9" y1="17" x2="15" y2="17"></line></svg></div><h3>Smart Cost Price (MAC)</h3><p>The software automatically averages the cost of raw materials during purchases and fairly distributes delivery costs across materials proportionally to their value, not equally.</p><div class="mini-ui"><div class="mini-row"><span class="label">Buttero Leather (Cognac):</span><span class="val">$50.00 <span class="addition">+$5.00</span></span></div><div class="mini-row"><span class="label">Italian Buckles:</span><span class="val">$10.00 <span class="addition">+$1.00</span></span></div><div class="delivery-badge">Batch delivery: $6.00 (distributed by value)</div></div></div><div class="bento-card"><div class="bento-icon-wrapper"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="4" width="20" height="16" rx="2" ry="2"></rect><line x1="12" y1="4" x2="12" y2="20"></line><line x1="2" y1="12" x2="22" y2="12"></line></svg></div><h3>Mixed Finances</h3><p>Don&#39;t artificially separate your personal wallet and the workshop&#39;s cash register. The system will automatically show when your project pays off its investments.</p><div class="mini-ui"><div class="balance-title">Business Capital + Personal Funds</div><div class="balance-bar"><div class="bar-fill positive" style="width:60%;"></div><div class="bar-fill negative" style="width:40%;"></div></div><div class="balance-labels"><span>Assets: $1,500.00</span><span class="neg">Cash Flow: -$500.00</span></div></div></div><div class="bento-card"><div class="bento-icon-wrapper"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"></path></svg></div><h3>Smart Workbench</h3><p>Plan your production queue. The program will analyze raw material stock and show resource shortages from top to bottom.</p><div class="mini-ui"><div class="queue-item"><span><span class="status-dot green"></span>Adler Backpack (x1)</span><span class="badge-ready">Secured</span></div><div class="queue-item"><span><span class="status-dot red"></span>Bifold Wallet (x2)</span><span class="badge-deficit">Material Shortage</span></div></div></div><div class="bento-card"><div class="bento-icon-wrapper"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div><h3>Time ROI Rating (Profitability)</h3><p>Find out how much real profit one hour of work on each specific product brings to your workshop.</p><div class="mini-ui"><div class="roi-item"><span class="name">Passport Cover:</span><span class="roi-val green">$15.00 / h</span></div><div class="roi-item"><span class="name">Complex Bag:</span><span class="roi-val muted">$3.00 / h</span></div></div></div><div class="bento-card span-2 highlight-card"><div class="bento-bg-gradient brand-glow"></div><div class="bento-icon-wrapper brand-text"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg></div><h3>100% Autonomy and Security (Local-First)</h3><p>The local SQLite database architecture with WAL journaling and automatic rotation backups (GFS) will carefully protect your numbers from power outages and PC crashes. The program does not require the internet to work — your financial secrets remain only on your computer.</p></div></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Single pipeline: from raw materials to net profit</h2></div><div class="sleek-pipeline"><div class="sleek-step"><div class="step-badge">01</div><h3>Supply</h3><p>Add assets to the Workshop and purchase materials for the Warehouse.</p><div class="step-footer">Result: capital is formed.</div></div><div class="sleek-step"><div class="step-badge">02</div><h3>Calculator</h3><p>Create a product recipe, set expenses, and labor time.</p><div class="step-footer">Result: cost calculation.</div></div><div class="sleek-step"><div class="step-badge">03</div><h3>Production</h3><p>Launch the batch to the Workbench and deliver to the Showcase.</p><div class="step-footer">Result: product with FIFO price.</div></div><div class="sleek-step"><div class="step-badge">04</div><h3>Sales</h3><p>Issue a receipt accounting for logistics and channel commissions.</p><div class="step-footer">Result: net profit growth.</div></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="section-header"><h2 class="gradient-text">PRO-level Ecosystem</h2></div><div class="bento-grid pro-grid"><div class="bento-card span-full flex-row"><div class="card-content"><div class="bento-icon-wrapper brand-text"><svg viewBox="0 0 24 24" width="28" height="28" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2 12 2"></polygon><polyline points="2 17 12 22 22 17"></polyline><polyline points="2 12 12 17 22 12"></polyline></svg></div><h3>Multi-Workspaces</h3><p>Running several directions? (e.g. leathercraft and PDF pattern sales). Create an unlimited number of isolated databases in one window with instant switching and a single ZIP backup.</p><span class="pro-tag">Available templates: Production. Coming soon: Services, Retail.</span></div></div><div class="bento-card"><div class="bento-icon-wrapper brand-text"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><line x1="12" y1="8" x2="12" y2="16"></line><line x1="8" y1="12" x2="16" y2="12"></line></svg></div><h3>&quot;My Capital&quot; (Personal Finances)</h3><p>Don&#39;t type in every supermarket receipt! Just update your bank card balances once a month, and the program will calculate your daily expenses via the profit delta (P&amp;L) of your businesses.</p></div><div class="bento-card"><div class="bento-icon-wrapper brand-text"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div><h3>Cross-cutting Modules (Soon)</h3><p>Specialized plugins (e.g. pattern generation, hide area calculation) that will work across all your workspaces simultaneously.</p></div></div></div></div><div class="custom-section section-dark-1"><div class="glow-bg center-glow"></div><div class="section-container"><div class="section-header"><h2 class="gradient-text">Choose a convenient format</h2></div><div class="sleek-pricing"><div class="pricing-card"><div class="p-header"><h4>Free</h4><div class="p-price">$0</div><p>For start and evaluation</p></div><ul class="p-features"><li><i></i> All 9 working tabs</li><li><i></i> WAL Security and Backups</li><li class="warning"><i></i> Limit: up to 20 receipts (sales)</li><li class="disabled"><i></i> Multi-workspaces</li><li class="disabled"><i></i> &quot;My Capital&quot; tab</li><li class="disabled"><i></i> Cross-cutting modules</li></ul></div><div class="pricing-card standard"><div class="p-header"><h4>Standard</h4><div class="p-price">Subscription <span class="or-divider">or</span> Lifetime</div><p>For a stable workshop</p></div><ul class="p-features"><li><i></i> All 9 working tabs</li><li><i></i> WAL Security and Backups</li><li class="active"><i></i> <b>Unlimited sales</b></li><li class="disabled"><i></i> Multi-workspaces</li><li class="disabled"><i></i> &quot;My Capital&quot; tab</li><li><i></i> Cross-cutting modules <em>(Add-on)</em></li></ul></div><div class="pricing-card pro-card"><div class="pro-glow"></div><div class="pro-badge">Maximum</div><div class="p-header"><h4>PRO</h4><div class="p-price">One-time expansion</div><p>For multiple directions</p></div><ul class="p-features"><li><i></i> All 9 working tabs</li><li><i></i> WAL Security and Backups</li><li class="active"><i></i> <b>Unlimited sales</b></li><li class="active-pro"><i></i> <b>Multi-workspaces</b></li><li class="active-pro"><i></i> <b>&quot;My Capital&quot; tab</b></li><li><i></i> Cross-cutting modules <em>(Add-on)</em></li></ul></div></div><div class="pricing-notice"><strong>💡 Important about the Free limit:</strong> You can test the free version as much as you want (there is no timer). The limit of 20 receipts is a safety catch. Attempting to bypass it by deleting old sales will destroy your historical analytics and balances. Buying a license is an investment in keeping your business numbers clean. </div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Frequently Asked Questions</h2></div><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Do I need the internet to work with the program?</summary><div class="faq-content"><p><strong>No.</strong> OmniCraft ERP is a Local-First application. It is installed on your computer, and the entire database (SQLite) is stored locally on your hard drive. You can work fully in a garage or basement without network access.</p></div></details><details class="faq-item"><summary class="faq-summary">What happens if my PC crashes? Will I lose my data?</summary><div class="faq-content"><p>The program has a powerful system of automatic background backups (GFS standard). The software regularly takes snapshots of the database (daily, weekly, monthly, and at every closing).</p><p>You can go to the &quot;File ➔ Export Data&quot; menu at any time and export a single ZIP archive with all your data to a flash drive or the cloud, so in case of a breakdown, you can restore everything on a new device in 10 seconds.</p></div></details><details class="faq-item"><summary class="faq-summary">What happens when I reach the 20 sales limit in the Free version?</summary><div class="faq-content"><p>The program will switch to a safe <strong>&quot;Read-only&quot;</strong> mode for final operations. You will no longer be able to issue new receipts in the POS terminal or release new batches from the Workbench.</p><p>However, <strong>your data will not be locked or deleted</strong>. You will still be able to enter the program, view analytics, export backups, and use the calculator. As soon as you purchase and enter the license key in the Settings, the limit will be lifted instantly.</p></div></details><details class="faq-item"><summary class="faq-summary">Is there a version for Mac OS or Linux?</summary><div class="faq-content"><p>Currently, we are compiling and testing the installation file only for Windows OS (10/11).</p><p>However, the OmniCraft ERP architecture is cross-platform. Database files are fully compatible between systems. We plan to release native builds for Mac OS and Linux in the future.</p></div></details></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="sleek-about"><div class="about-quote"> &quot;OmniCraft ERP is not a product of a faceless corporation. The program was born in the dust and smell of genuine leather, to the sound of a hammer and the hum of machines.&quot; </div><div class="about-text"> System creator — <a href="https://nmurashkin.ru" target="_blank"><strong>N. Murashkin Leathercraft Workshop</strong></a>. We create physical products for decades, and we put the same philosophy into this code. <br><br>The program speaks to the crafter in the language of profitability and common sense, not complex accounting entries. </div></div></div></div><div class="custom-cta-block"><div class="glow-bg bottom-glow"></div><h2 class="gradient-text">Ready to bring order to your workshop?</h2><p class="cta-subtitle" style="color:var(--vp-c-text-2);max-width:600px;margin:0 auto 2rem;line-height:1.6;">Quick start: enter your current leather stock, specify your historical cash balance — and the math will add up on the very first day.</p><div class="cta-buttons"><a class="vp-button brand" href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe">⬇ Download for Windows</a><a class="vp-button alt" href="/docs/introduction">📖 Read Documentation</a></div><div class="footer-links"><a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank">GitHub Repository</a><a href="/docs/licenses">Licenses</a><a href="/docs/about">About Developer</a></div></div>',11)])])}const f=a(r,[["render",c]]);export{g as __pageData,f as default};
